def is_valid(A):
    A = sorted(list(A))
    n = len(A)
    for i in range(n):
        for j in range(i + 1, n):
            for l in range(j + 1, n):
                x, y, z = A[i], A[j], A[l]
                if (x + y + z) % 2 == 0 and x + y > z:
                    return False
    return True

def solve_small(n):
    max_size = 0
    for i in range(1 << n):
        subset = []
        for j in range(n):
            if (i >> j) & 1:
                subset.append(j + 1)
        if is_valid(subset):
            max_size = max(max_size, len(subset))
    return max_size

for n in range(1, 11):
    print(f"n={n}, max_size={solve_small(n)}")

def find_max_subset(n):
    max_subset = []
    max_size = 0
    for i in range(1 << n):
        subset = []
        for j in range(n):
            if (i >> j) & 1:
                subset.append(j + 1)
        if is_valid(subset):
            if len(subset) > max_size:
                max_size = len(subset)
                max_subset = subset
    return max_subset, max_size

for n in range(1, 11):
